import * as jose from 'jose';
import { APIError, parseCookies } from 'payload';
import { JWTValidationError, validatePayloadAdminToken } from '../../auth/jwt-validator.js';
import { getInfraEnvironment } from '../../constants.js';
import { createDebugLogger } from '../utilities/createDebugLogger.js';
import { getTokenExp } from '../utilities/getTokenExp.js';
import { mergeHeaders } from '../utilities/mergeHeaders.js';
import { refreshTokens } from '../utilities/refreshTokens.js';
export class Strategy {
    clientID;
    collection;
    collectionOptions;
    cookieName;
    debug;
    // eslint-disable-next-line @typescript-eslint/no-explicit-any
    debugLog;
    identityMetadataURL;
    jwks;
    meta;
    metaLastFetchedTime;
    metaPromise;
    metaPromiseResolve;
    name;
    pluginOptions;
    verify;
    constructor(options){
        this.verify = options.verify;
        this.cookieName = options.cookieName;
        this.clientID = options.clientID;
        this.identityMetadataURL = options.identityMetadata;
        this.name = options.strategyName;
        this.collection = options.collection;
        this.collectionOptions = options.collectionOptions;
        this.pluginOptions = options.pluginOptions;
        this.debug = options.debug || false;
        // eslint-disable-next-line no-console, @typescript-eslint/no-explicit-any
        this.debugLog = options.debug ? (...args)=>console.log(...args) : ()=>null;
        // Prevent wokiness with `this`
        this.ensureMeta = this.ensureMeta.bind(this);
    }
    async authenticate({ canSetHeaders, headers, payload }) {
        const debugLogger = createDebugLogger(payload, this.debug);
        await this.ensureMeta();
        const cookies = parseCookies(headers);
        let oauthToken = cookies.get(this.cookieName);
        const refreshToken = cookies.get(`${this.cookieName}-refresh`);
        debugLogger.info({
            hasOauthToken: !!oauthToken,
            hasRefreshToken: !!refreshToken,
            msg: 'Retrieved tokens from cookies'
        });
        if (!this.collectionOptions.disableJWTFromHeader) {
            // Parse Authorization header if exists
            const jwtFromHeader = headers.get('authorization');
            if (typeof jwtFromHeader === 'string' && jwtFromHeader.startsWith('Bearer ')) {
                debugLogger.info({
                    msg: 'Found bearer token in authorization header'
                });
                oauthToken = jwtFromHeader.replace('Bearer ', '');
            }
        }
        if (!oauthToken) {
            // Attempt refresh even when canSetHeaders=false (e.g., during RSC navigation).
            // This allows authentication to succeed for the current request even when
            // cookies cannot be updated. The cookie will be refreshed on the next
            // full page load when canSetHeaders=true.
            if (refreshToken) {
                debugLogger.info({
                    msg: 'No access token found, but refresh token exists. Attempting to refresh...'
                });
                const refreshed = await refreshTokens({
                    payload,
                    refreshToken,
                    strategy: this
                });
                if (refreshed) {
                    const verifyResult = await this.verify({
                        headers,
                        payload,
                        token: refreshed.decodedOauthToken
                    });
                    debugLogger.info({
                        msg: 'Token refreshed. Verifying...',
                        verifyResult
                    });
                    // Only return response headers (to set cookies) when canSetHeaders is true.
                    // During RSC navigation, canSetHeaders=false because response streaming
                    // has already started and cookies cannot be modified.
                    if (canSetHeaders) {
                        if (verifyResult.responseHeaders) {
                            mergeHeaders(verifyResult.responseHeaders, refreshed.headers);
                        }
                        return {
                            responseHeaders: refreshed.headers,
                            user: verifyResult.user
                        };
                    }
                    // Authenticate this request without updating cookies
                    return {
                        user: verifyResult.user
                    };
                } else {
                    debugLogger.info({
                        msg: 'Token refresh failed'
                    });
                }
            }
            return {
                user: null
            };
        }
        let oauthTokenVerifyResult = null;
        // First, try to verify token
        if (oauthToken) {
            oauthTokenVerifyResult = await this.jwtVerify({
                payload,
                token: oauthToken
            });
            // If verify comes back null, there is no user
            if (oauthTokenVerifyResult === null) {
                return {
                    user: null
                };
            }
            // If verify comes back truthy, use it
            // but first set exp from refresh token
            // because access exp is likely very short lived
            if (typeof oauthTokenVerifyResult === 'object' && !(oauthTokenVerifyResult instanceof Error)) {
                if (refreshToken) {
                    const refreshTokenExp = getTokenExp({
                        debugLogger,
                        token: refreshToken
                    });
                    if (refreshTokenExp) {
                        oauthTokenVerifyResult.exp = refreshTokenExp;
                    }
                }
                return this.verify({
                    headers,
                    payload,
                    token: oauthTokenVerifyResult
                });
            }
        }
        // Handle expired access token with valid refresh token.
        // Same pattern as above: refresh regardless of canSetHeaders to support RSC navigation,
        // but only update cookies when canSetHeaders=true.
        if (oauthTokenVerifyResult instanceof JWTValidationError && oauthTokenVerifyResult.code === 'EXPIRED' && refreshToken && !this.collectionOptions.usePayloadJWT) {
            const refreshed = await refreshTokens({
                payload,
                refreshToken,
                strategy: this
            });
            debugLogger.info({
                msg: 'Token expired. Refreshing...'
            });
            if (refreshed) {
                const verifyResult = await this.verify({
                    headers,
                    payload,
                    token: refreshed.decodedOauthToken
                });
                debugLogger.info({
                    msg: 'Token refreshed. Verifying...',
                    verifyResult
                });
                if (canSetHeaders) {
                    if (verifyResult.responseHeaders) {
                        mergeHeaders(verifyResult.responseHeaders, refreshed.headers);
                    }
                    return {
                        responseHeaders: refreshed.headers,
                        user: verifyResult.user
                    };
                }
                // Authenticate this request without updating cookies
                return {
                    user: verifyResult.user
                };
            } else {
                debugLogger.info({
                    msg: 'Token refresh failed'
                });
            }
        }
        return {
            user: null
        };
    }
    async ensureMeta() {
        if (this.metaPromise) {
            this.debugLog('strategy - metaPromise exists. Waiting for it to resolve...');
            await this.metaPromise;
        }
        // If no meta or this.metaLastFetchedTime is more than 24 hours old, fetch meta
        if (!this.metaLastFetchedTime || Date.now() - this.metaLastFetchedTime.getTime() > 86_400_000) {
            this.debugLog(`Meta is stale. Fetching... Last fetched: ${this.metaLastFetchedTime || 'never'}`);
            await this.fetchMeta();
        }
    }
    async fetchMeta() {
        // If already in-flight, return the existing promise
        if (this.metaPromise) {
            this.debugLog('fetchMeta - returning existing metaPromise');
            return this.metaPromise;
        }
        this.debugLog('fetchMeta - creating new metaPromise...');
        // Build the shared promise
        this.metaPromise = (async ()=>{
            let lastError;
            for(let attempt = 1; attempt <= 5; attempt++){
                try {
                    this.meta = await fetch(this.identityMetadataURL).then((res)=>res.json());
                    if (this.meta) {
                        // TODO: This is a hack to get the DefaultLoginButton to work with dynamic OAuth client registration
                        this.meta.authorization_endpoint = this.meta?.authorization_endpoint + '/cms';
                    }
                    this.debugLog(`fetchMeta - success on attempt ${attempt}`);
                    if (this.meta?.jwks_uri) {
                        this.jwks = await fetch(this.meta.jwks_uri).then((res)=>res.json());
                    }
                    this.metaLastFetchedTime = new Date();
                    this.debugLog(`fetchMeta - finished at ${this.metaLastFetchedTime.toISOString()}`);
                    return;
                } catch (error) {
                    lastError = error;
                    this.debugLog(`fetchMeta - FAILED attempt ${attempt}/5: ${error?.message}`);
                    if (attempt < 5) {
                        // Exponential backoff (up to 1s)
                        await new Promise((resolve)=>setTimeout(resolve, Math.min(attempt * 200, 1000)));
                    }
                }
            }
            throw new APIError(`Failed to fetch identity metadata from "${this.identityMetadataURL}". Last error: ${lastError?.message ?? 'unknown'}`);
        })();
        try {
            await this.metaPromise;
        } finally{
            this.metaPromise = undefined;
        }
    }
    async generateOidcPEM(kid, alg) {
        const keys = this && this.jwks && Array.isArray(this.jwks.keys) ? this.jwks.keys : null;
        let pubKey = null;
        let foundKey = false;
        if (!kid) {
            throw new Error('kid is missing');
        }
        if (!alg) {
            throw new Error('alg is missing');
        }
        if (!keys) {
            throw new Error('keys is missing');
        }
        for (const key of keys){
            if (!('kid' in key) || key.kid !== kid) {
                continue;
            }
            const cryptoKey = await jose.importJWK(key, alg);
            if (!(cryptoKey instanceof CryptoKey)) {
                throw new Error('importJWK did not return a CryptoKey');
            }
            pubKey = await jose.exportSPKI(cryptoKey);
            foundKey = true;
            break;
        }
        if (!foundKey) {
            throw new Error('a key with the specific kid cannot be found');
        }
        if (!pubKey) {
            throw new Error('generating public key pem failed');
        }
        return pubKey;
    }
    async jwtVerify({ payload, token }) {
        try {
            const audience = payload.config.custom.figma.environmentId;
            if (!audience) {
                throw new Error('Cannot validate token audience: environmentId is not configured');
            }
            const verified = await validatePayloadAdminToken({
                audience,
                environment: getInfraEnvironment(),
                token
            });
            if (typeof verified !== 'string') {
                return verified;
            }
        } catch (err) {
            payload.logger.error({
                err,
                msg: 'Error verifying jwt token'
            });
            if (err instanceof Error) {
                return err;
            }
            return null;
        }
        return null;
    }
}
